import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def g2(a, b):
    while b:
        a, b = b, a % b
    return a
c = 0
for idx in range(n - 1):
    if (g2(a[idx], 10) == 1) and (g2(a[idx + 1], 10) == 1):
        c += 1
print(c)

